'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function all(chunks, opts) {
  const p = createParser(opts);
  const out = [];
  for (const c of chunks) out.push(...p.push(c));
  return out.concat(p.end());
}
function everySplit(text, opts) {
  const whole = parse(text, opts);
  for (let i = 0; i <= text.length; i++)
    for (let j = i; j <= text.length; j++)
      assert.deepEqual(all([text.slice(0, i), '', text.slice(i, j), text.slice(j)], opts), whole, JSON.stringify([text, i, j]));
  return whole;
}

assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\uFEFF'), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\r\nb\rc\n'), [['a'], ['b'], ['c']]);
assert.deepEqual(everySplit('\uFEFFa,"x""y\r\nz",\r\n\r\nb"c"d,\uFEFF\r'), [['a', 'x"y\r\nz', ''], [''], ['b"c"d', '\uFEFF']]);
assert.deepEqual(everySplit('a;"b;c"\r\n', { delimiter: ';' }), [['a', 'b;c']]);
assert.deepEqual(parse(',,'), [['', '', '']]);
assert.deepEqual(parse('""'), [['']]);

// streaming: CR completes record immediately
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => createParser().push(1), TypeError);

for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

// line numbers
for (const chunks of [['"a\r\nb" x'], ['"a\r', '\nb" x'], ['a\n"b\rc\n\r\n"x']]) {
  assert.throws(() => all(chunks), e => e instanceof SyntaxError && /line (\d+)/.exec(e.message)[1] === String(chunks.join('').split(/\r\n|\r|\n/).length));
}
assert.throws(() => parse('a\r\n"b\r\nc'), e => e instanceof SyntaxError && /line 3\b/.test(e.message));

assert.deepEqual(parse('x,x,x_2,x\n1\n', { header: true }), [{ x: '1', x_2: '', x_2_2: '', x_3: '' }]);
const o = parse('__proto__\nv', { header: true })[0];
assert.equal(Object.getPrototypeOf(o), Object.prototype);
assert.deepEqual(Object.keys(o), ['__proto__']);
console.log('ok');
